/// <summary>
/// Extension of formDataSource PurchTable in form PurchTable
/// </summary>
[ExtensionOf(formDataSourceStr(PurchTable, PurchTable))]
final class AVAPurchTable_PurchTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Extension of validateWrite method
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    List                    purchTable2LineUpdateFields;
    ListEnumerator          purchTable2LineUpdateFieldsEnumerator;
    PurchTable2LineField    purchTable2LineField;
    PurchTable              avaPurchTable = this.formRun().dataSource('PurchTable').cursor();
    boolean                 orderConfirmationUpdateLoc = avaPurchTable.AVAOrderConfirmation != avaPurchTable.orig().AVAOrderConfirmation;

    boolean ret = next validateWrite();

    if (orderConfirmationUpdateLoc
            && ret
            && element.purchTable2LineUpdatePrompt)
    {
        purchTable2LineUpdateFields = List::create(element.purchTable2LineUpdatePrompt.packedSalesPurchTableToLineUpdateFields());
        purchTable2LineUpdateFieldsEnumerator = purchTable2LineUpdateFields.getEnumerator();

        while (purchTable2LineUpdateFieldsEnumerator.moveNext())
        {
            purchTable2LineField = purchTable2LineUpdateFieldsEnumerator.current();

            if (purchTable2LineField.parmFieldId() == fieldnum(PurchTable, AVAOrderConfirmation)
                    && purchTable2LineField.parmUpdateLines())
            {
                // update line order confirmation when header order confirmation has changed
                avaPurchTable.avaUpdateLineOrderConfirmation();
                break;
            }
        }
    }

    return ret;

}
